class FloodEvent {
  final List<String> states;
  final int startYear;
  final int startMonth;
  final int startDay;
  final int endYear;
  final int endMonth;
  final int endDay;
  final String subtype; // e.g. "Riverine flood", "Flash flood", "Flood (General)"
  final String location;
  final int deaths;
  final int affected;
  final String cause;

  const FloodEvent({
    required this.states,
    required this.startYear,
    required this.startMonth,
    required this.startDay,
    required this.endYear,
    required this.endMonth,
    required this.endDay,
    required this.subtype,
    required this.location,
    required this.deaths,
    required this.affected,
    required this.cause,
  });

  DateTime get startDate => DateTime(startYear, startMonth, startDay);
  DateTime get endDate => DateTime(endYear, endMonth, endDay);
}

